// Um item por anexo PDF, com metadata do email.
const items = $input.all();
const out = [];
for (const item of items) {
  const j = item.json || {};
  const msgId = j.id || j.threadId || ('nocid-' + Date.now());
  const headers = (j.payload && j.payload.headers) || [];
  const get = (n) => { const h = headers.find(x => x && x.name && x.name.toLowerCase() === n); return h ? h.value : (j[n] || ''); };
  const subject = get('subject') || '(sem assunto)';
  const from = get('from') || '';
  const date = j.internalDate ? new Date(Number(j.internalDate)).toISOString().slice(0,10) : (j.date || new Date().toISOString().slice(0,10));
  if (!item.binary) continue;
  for (const key of Object.keys(item.binary)) {
    const bin = item.binary[key];
    const fileName = (bin.fileName || '').trim();
    if (!fileName) continue;
    const isPdf = (bin.mimeType || '').toLowerCase().includes('pdf') || fileName.toLowerCase().endsWith('.pdf');
    if (!isPdf) continue;
    out.push({ json: { msgId: String(msgId), subject, from, date, fileName }, binary: { data: bin } });
  }
}
console.log('anexos pdf: ' + out.length);
return out;

// Markdown -> chunks (cap duro ~850 chars) -> entries.
// Metadata vem do "Preparar Anexos" por alinhamento de indice (o HTTP do toolbox descarta o json anterior).
const items = $input.all();
let metas = [];
try { metas = $('Preparar Anexos').all().map(i => i.json); } catch (e) {}

const splitLong = (p, max) => {
  if (p.length <= max) return [p];
  const parts = [];
  let cur = '';
  for (const ln of p.split('\n')) {
    if ((cur + '\n' + ln).length > max && cur) { parts.push(cur); cur = ln; }
    else cur = cur ? cur + '\n' + ln : ln;
    while (cur.length > max) { parts.push(cur.slice(0, max)); cur = cur.slice(max); }
  }
  if (cur) parts.push(cur);
  return parts;
};

const results = [];
for (let idx = 0; idx < items.length; idx++) {
  const j = items[idx].json || {};
  const m = metas[idx] || {};
  const base = {
    msgId: String(m.msgId || j.msgId || 'sem-id'),
    fileName: m.fileName || j.fileName || 'desconhecido',
    subject: m.subject || j.subject || '(sem assunto)',
    from: m.from || j.from || '',
    date: m.date || j.date || ''
  };
  const md = typeof j.markdown === 'string' ? j.markdown : '';

  if (!md && j.error) {
    results.push({ json: {
      namespace: '/memory/condominio', source_agent: 'n8n-condominio',
      entries: [{ key: base.msgId + '::' + base.fileName + '::erro-toolbox',
        content: '[' + base.subject + ' | ' + base.date + ' | ' + base.fileName + '] FALHA na extracao de texto (toolbox). Revisar PDF original.',
        metadata: { kind: 'condominio-doc-erro-toolbox', title: base.subject, date: base.date, file: base.fileName } }],
      fileName: base.fileName, nChunks: 1, toolboxError: true,
      errDetail: (j.error && (j.error.message || j.error.description)) || 'desconhecido'
    } });
    continue;
  }

  if (!md || md.length < 200) {
    results.push({ json: {
      namespace: '/memory/condominio', source_agent: 'n8n-condominio',
      entries: [{ key: base.msgId + '::' + base.fileName + '::scan',
        content: '[' + base.subject + ' | ' + base.date + ' | ' + base.fileName + '] Documento SEM camada de texto (provavel scan) - placeholder; revisar PDF original.',
        metadata: { kind: 'condominio-doc-scan', title: base.subject, date: base.date, file: base.fileName } }],
      fileName: base.fileName, nChunks: 1, skipped: true
    } });
    continue;
  }

  const paragraphs = md.split(/\n\s*\n/).map(p => p.trim()).filter(Boolean);
  const chunks = [];
  let cur = '';
  for (const p0 of paragraphs) {
    for (const p of splitLong(p0, 850)) {
      if ((cur + '\n\n' + p).length > 850 && cur) { chunks.push(cur); cur = p; }
      else cur = cur ? cur + '\n\n' + p : p;
    }
  }
  if (cur) chunks.push(cur);

  const entries = chunks.map((c, i) => ({
    key: base.msgId + '::' + base.fileName + '::' + i,
    content: '[' + base.subject + ' | ' + base.date + ' | ' + base.fileName + ']\n\n' + c,
    metadata: { kind: 'condominio-doc', title: base.subject, date: base.date, sender: base.from, file: base.fileName, chunk_index: i, chunks: chunks.length }
  }));
  results.push({ json: { namespace: '/memory/condominio', source_agent: 'n8n-condominio', entries, fileName: base.fileName, nChunks: chunks.length } });
}
console.log('docs ok: ' + results.filter(r => !r.json.skipped && !r.json.toolboxError).length + ', scan: ' + results.filter(r => r.json.skipped).length + ', toolbox erro: ' + results.filter(r => r.json.toolboxError).length);
return results;

const items = $input.all();
const out = [];
for (const item of items) {
  const j = item.json || {};
  const entries = Array.isArray(j.entries) ? j.entries : [];
  for (const e of entries) {
    out.push({ json: {
      namespace: j.namespace || '/memory/condominio',
      source_agent: j.source_agent || 'n8n-condominio',
      key: e.key, content: e.content, metadata: e.metadata || {},
      fileName: j.fileName
    }});
  }
}
console.log('entries: ' + out.length);
return out;

// Um UNICO item com o batch completo (JSON) para o Upsert. Contorna o bug do Postgres node v2.5 com queryReplacement tipo array (executava 1x soh, primeiro item — n8n #31704): agora ha UM item e UM bind $1::jsonb. Falhas de embed ficam de fora; proximo ciclo recupera (idempotente).
const items = $input.all();
let srcs = [];
try { srcs = $('Separar Entries').all().map(i => i.json); } catch (e) {}
if (items.length !== srcs.length) throw new Error('desalinhamento embed/entradas: ' + items.length + ' vs ' + srcs.length);
const batch = [];
let embedFails = 0;
for (let i = 0; i < items.length; i++) {
  const emb = items[i].json;
  const src = srcs[i] || {};
  let embArr = null;
  if (Array.isArray(emb)) embArr = emb;
  else if (emb && Array.isArray(emb.data) && emb.data[0] && Array.isArray(emb.data[0].embedding)) embArr = emb.data[0].embedding;
  else if (emb && Array.isArray(emb.embeddings) && Array.isArray(emb.embeddings[0])) embArr = emb.embeddings[0];
  if (!embArr) { embedFails++; continue; }
  batch.push({
    namespace: src.namespace, key: src.key, content: src.content,
    embedding: JSON.stringify(embArr),
    metadata: Object.assign({ key: src.key }, src.metadata || {}),
    source_agent: src.source_agent
  });
}
console.log('batch: ' + batch.length + ', embed falhou: ' + embedFails);
return [{ json: { batch: JSON.stringify(batch), count: batch.length, embedFails } }];

// Resumo v4: upsert agora e UM batch atomico; upsertOk = chunks escritos na BD (count do batch), nao itens de output do node (que eram 1 e escondiam a perda).
let embeds = [], entries = [], docsIn = [];
try { embeds = $('Embed TEI').all(); } catch (e) {}
try { entries = $('Separar Entries').all(); } catch (e) {}
try { docsIn = $('Chunk e Payload').all(); } catch (e) {}
const ups = $input.all();
const upsertErrors = ups.filter(u => u.json && u.json.error).length;

let batchCount = 0;
try { batchCount = $('Build Params').first().json.count || 0; } catch (e) {}
const upsertOk = upsertErrors ? 0 : batchCount;

const failedFiles = {};
for (let i = 0; i < entries.length; i++) {
  const e2 = entries[i].json || {};
  const emb = (embeds[i] || {}).json || {};
  const embBad = emb.error || !Array.isArray(emb);
  if (embBad) { const f = e2.fileName || (e2.metadata && e2.metadata.file) || '?'; failedFiles[f] = (failedFiles[f] || 0) + 1; }
}

let docs = 0, chunks = 0, skipped = 0, toolboxFails = 0;
const parts = [];
for (const d of docsIn) {
  const j = d.json || {};
  if (j.toolboxError) { toolboxFails++; parts.push('- ' + (j.fileName || '?') + ': TOOLBOX falhou (' + (j.errDetail || '?') + ')'); continue; }
  if (j.skipped) { skipped++; parts.push('- ' + (j.fileName || '?') + ': SEM TEXTO (scan?) - revisar'); continue; }
  if (failedFiles[j.fileName]) continue;
  docs++; chunks += (j.nChunks || 0);
}
const failFiles = Object.keys(failedFiles);
for (const f of failFiles) parts.push('- ' + f + ': ERRO embed (' + failedFiles[f] + ' chunks)');
if (upsertErrors) parts.push('- UPSERT falhou (' + upsertErrors + ') - batch NAO escrito');
const fails = toolboxFails + failFiles.length + (upsertErrors ? 1 : 0);
let message = 'Condominio -> Mnemosyne: ' + upsertOk + '/' + chunks + ' chunks na BD';
if (docs) message += ' (' + docs + ' doc(s))';
if (skipped) message += '; ' + skipped + ' sem texto (revisar)';
if (fails) message += '; ' + fails + ' FALHA(S)';
message += ' [upserts ok: ' + upsertOk + ']';
if (parts.length) message += '\n' + parts.join('\n');
return [{ json: { message, docs, chunks, skipped, fails, upsertOk } }];

// Deixa passar apenas docs AINDA NAO indexados (nenhuma entrada com prefixo msgId::fileName:: na BD).
// Item do check vem 1:1 alinhado com Preparar Anexos; sem resposta do check => trata como novo (processa e notifica).
const checks = $input.all();
let docs = [];
try { docs = $('Preparar Anexos').all(); } catch (e) {}
const out = [];
for (let i = 0; i < docs.length; i++) {
  const c = (checks[i] || {}).json || {};
  if (c.ja_indexado === true) continue;
  const d = docs[i];
  out.push({ json: d.json, binary: d.binary });
}
console.log('docs novos: ' + out.length + '/' + docs.length);
return out;

